def preorder(root):
    answer, stack = [], [root] if root else []
    while stack:
        node = stack.pop()
        answer.append(node.val)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)
    return answer

def inorder(root):
    answer, stack, node = [], [], root
    while node is not None or stack:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        answer.append(node.val)
        node = node.right
    return answer

def postorder(root):
    answer, stack = [], [root] if root else []
    while stack:
        node = stack.pop()
        answer.append(node.val)
        if node.left:
            stack.append(node.left)
        if node.right:
            stack.append(node.right)
    return answer[::-1]

