def solve(root, order="in"):
    if order not in ("pre", "in", "post"):
        raise ValueError("order must be pre, in or post")
    answer, stack = [], [(root, False)] if root else []
    while stack:
        node, ready = stack.pop()
        if ready:
            answer.append(node.val)
            continue
        left = [(node.left, False)] if node.left else []
        right = [(node.right, False)] if node.right else []
        current = [(node, True)]
        actions = (current + left + right if order == "pre" else
                   left + current + right if order == "in" else
                   left + right + current)
        stack.extend(reversed(actions))
    return answer

