class Node:
    def __init__(self, val, left=None, right=None, next=None):
        self.val, self.left, self.right, self.next = val, left, right, next

def solve(root):
    if root is None:
        return None
    root.next = None
    head = root
    while head:
        dummy = Node(0)
        tail = dummy
        node = head
        while node:
            for child in (node.left, node.right):
                if child is not None:
                    tail.next = child
                    tail = child
            node = node.next
        tail.next = None
        head = dummy.next
    return root

