def solve(inorder, postorder):
    index = {value: i for i, value in enumerate(inorder)}
    cursor = len(postorder) - 1
    def build(lo, hi):
        nonlocal cursor
        if lo > hi:
            return None
        value = postorder[cursor]
        cursor -= 1
        mid = index[value]
        root = TreeNode(value)
        root.right = build(mid + 1, hi)
        root.left = build(lo, mid - 1)
        return root
    return build(0, len(inorder) - 1)

