def solve(root):
    stack, node = [], root
    previous = best = None
    while node is not None or stack:
        while node:
            stack.append(node)
            node = node.left
        node = stack.pop()
        if previous is not None:
            gap = node.val - previous
            best = gap if best is None else min(best, gap)
        previous = node.val
        node = node.right
    if best is None:
        raise ValueError("at least two nodes are required")
    return best

