            answer.append(node.val)
            queue.append(node.left)
            queue.append(node.right)
    while answer and answer[-1] is None:
        answer.pop()
    return answer

def solve(root):
    previous = None
    stack, node = [], root
    while node is not None or stack:
        while node:
            stack.append(node)
            node = node.left
        node = stack.pop()
        if previous is not None and node.val <= previous:
            return False
        previous = node.val
        node = node.right
    return True

from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def tree(values):
    """按层序构造测试树；None 表示缺失孩子。"""
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue = deque([root])
    i = 1
    while queue and i < len(values):
        node = queue.popleft()
        for side in ("left", "right"):
            if i >= len(values):
                break
            value = values[i]
            i += 1
            if value is not None:
                child = TreeNode(value)
                setattr(node, side, child)
                queue.append(child)
    return root

def values(root):
    """返回去掉末尾空位的层序数组，便于核验结构。"""
    if root is None:
        return []
    answer, queue = [], deque([root])
    while queue:
        node = queue.popleft()
        if node is None:
            answer.append(None)
        else:
            answer.append(node.val)
            queue.append(node.left)
            queue.append(node.right)
    while answer and answer[-1] is None:
        answer.pop()
    return answer

def solve(root):
    if root is None:
        return {"nodes": 0, "height": 0, "width": 0}
    queue = deque([root])
    nodes = height = width = 0
    while queue:
        size = len(queue)
        height += 1
        width = max(width, size)
        nodes += size
        for _ in range(size):
            node = queue.popleft()
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
    return {"nodes": nodes, "height": height, "width": width}
